def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    opp_pressures = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            pressure = 0.0
            if opp.get('no_water_days', 0) >= 1:
                pressure += 1.0
            if opp.get('hp', 10) <= 4:
                pressure += 1.0
            if opp.get('budget', 0) > budget:
                pressure += 0.5
            opp_pressures.append(pressure)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    urgent_opps = 0
    for opp in alive:
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_opps += 1

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        target = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
        if tight_supply:
            target = max(target, 78.0)
        return float(min(budget, target))

    if hp <= 4 or no_water_days >= 1:
        target = max(0.72 * DAILY_SALARY, min(highest_prev + 2.0, 0.95 * DAILY_SALARY))
        if tight_supply:
            target = max(target, 60.0)
        return float(min(budget, target))

    if loose_supply and highest_prev >= 120:
        return float(min(budget, 8.0))

    if tight_supply:
        if highest_prev >= 180:
            target = 28.0
        elif highest_prev >= 120:
            target = 42.0
        elif highest_prev >= 70:
            target = highest_prev + 1.5
        else:
            target = max(36.0, avg_prev * 0.7)
        if urgent_opps >= 2:
            target += 6.0
        return float(min(budget, target))

    if highest_prev >= 180:
        target = 12.0
    elif highest_prev >= 120:
        target = 20.0
    elif highest_prev >= 80:
        target = 30.0
    else:
        target = max(24.0, min(46.0, avg_prev * 0.55 + 6.0))

    if day >= 8 and hp >= 6:
        target *= 0.85

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # If our HP is critical, bid aggressively to avoid death.
    if hp <= 2.0:
        return float(min(budget, DAILY_SALARY * 0.95))

    # If someone already overbid yesterday, we can undercut slightly.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Cindy-like behavior: very high bids. Free-ride.
        if highest_prev_bid >= DAILY_SALARY * 1.8:
            # Moderate bid: enough to likely win some allocation, but cheaper than them.
            bid = DAILY_SALARY * 0.55
        # Other survivors bid mid-range: bid a bit above the median/high to secure.
        else:
            sorted_bids = sorted(yesterday_bids)
            mid = sorted_bids[int(len(sorted_bids) // 2)] if len(sorted_bids) > 0 else highest_prev_bid
            bid = max(DAILY_SALARY * 0.45, float(mid) * 1.05)
    else:
        bid = DAILY_SALARY * 0.55

    # Scale down as supply increases (more likely to get water without overpaying)
    # supply is in [15,25].
    if supply is not None:
        try:
            s = float(supply)
            # map s in [15,25] to multiplier in [1.05, 0.9]
            mult = 1.05 - (s - MIN_SUPPLY) * (0.15 / (MAX_SUPPLY - MIN_SUPPLY))
            bid *= mult
        except Exception:
            pass

    # Ensure we don't bid more than we can afford.
    bid = float(min(budget, bid))

    # If budget is too low, bid whatever remains (still try to get water).
    if bid <= 0.0:
        return 0.0

    # Slightly adjust by day to keep survival to the end (later days bid a touch more).
    # episode_days is 10 in meta state, but not provided here; we use day to infer.
    try:
        if day is not None and int(day) >= 8:
            bid = min(budget, bid * 1.15)
    except Exception:
        pass

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
